import ast, zlib

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
        kinds = sorted({type(n).__name__ for n in ast.walk(tree)})
        blob = ",".join(kinds).encode()
        v = zlib.crc32(blob) & 0xffffff
        return (v % 1000) / 1000.0
    except Exception:
        return 0.37

